-- Manuscript prose. Compatibility-critical: stale clients and queued offline saves
-- read id/content/word_count/version/updated_at/chapter_id directly, and Page IDs
-- are IndexedDB keys. In Rune 2.0 this table stores Scenes; Page ID = Scene ID.
create table public.pages (
  id           uuid default gen_random_uuid() not null,
  chapter_id   uuid not null,
  title        text not null,
  content      jsonb,
  word_count   integer default 0 not null,
  position     integer not null,
  created_at   timestamp with time zone default now() not null,
  updated_at   timestamp with time zone default now() not null,
  is_canonical boolean default false not null,
  version      integer default 1 not null
);

create table public.profiles (
  id                      uuid not null,
  username                text,
  display_name            text,
  avatar_url              text,
  xp                      integer default 0 not null,
  level                   integer default 1 not null,
  created_at              timestamp with time zone default now() not null,
  preferences             jsonb,
  stripe_customer_id      text,
  subscription_tier       text default 'free'::text,
  subscription_status     text default 'inactive'::text,
  subscription_price_id   text,
  subscription_period_end timestamp with time zone,
  has_written_first_words boolean default false not null,
  is_admin                boolean default false not null
);

