CREATE OR REPLACE FUNCTION public.account_word_total(p_candidate_page_id uuid DEFAULT NULL::uuid, p_candidate_word_count integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_total int;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  with existing_pages as (
    select
      p.id as page_id,
      case
        when p_candidate_page_id is not null and p.id = p_candidate_page_id
        then p_candidate_word_count
        else p.word_count
      end as word_count
    from public.chapters c
    join public.projects pr on pr.id = c.project_id
    join public.pages p on p.chapter_id = c.id
    where pr.user_id = auth.uid()
  ),
  new_page as (
    -- Synthetic row for a brand-new page not yet inserted anywhere.
    select p_candidate_word_count as word_count
    where p_candidate_page_id is null
      and p_candidate_word_count is not null
  )
  select coalesce(sum(word_count), 0)
  into v_total
  from (
    select word_count from existing_pages
    union all
    select word_count from new_page
  ) all_words;

  return v_total;
end;
$function$;

CREATE OR REPLACE FUNCTION public.bump_project_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  update public.projects
  set updated_at = now()
  where id = (
    select c.project_id
    from public.chapters c
    where c.id = new.chapter_id
  );

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.duplicate_project_checked(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_source public.projects%rowtype;
  v_source_chapter record;
  v_source_page record;
  v_new_project public.projects%rowtype;
  v_new_chapter_id uuid;
  v_new_title text;
  v_used_numbers int[];
  v_draft_num int;
  v_source_total int;
  v_account_total int;
  v_limit int;
begin
  perform public.lock_account_word_budget();

  select * into v_source
    from public.projects
   where id = p_project_id and user_id = auth.uid();

  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Project not found');
  end if;

  -- Every page in the source project, canonical or not — the same
  -- all-pages definition account_word_total() uses, see the migration
  -- header above for why. Computed directly here since the source project
  -- already exists and needs no substitution.
  select coalesce(sum(p.word_count), 0)
    into v_source_total
  from public.chapters c
  join public.pages p on p.chapter_id = c.id
  where c.project_id = p_project_id;

  if v_source_total > 0 then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_account_total := public.account_word_total();
      if v_account_total + v_source_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  -- Unique "— Draft N" title: smallest unused number starting at 2,
  -- preserving the exact gap-filling behavior of the prior JS
  -- implementation (not simply max+1). regexp_match() (singular) is a
  -- plain scalar function returning text[] or null — not a set-returning
  -- function, so it's called directly rather than via a LATERAL join.
  select array_agg((regexp_match(p.title, '— Draft (\d+)$'))[1]::int)
    into v_used_numbers
  from public.projects p
  where p.user_id = auth.uid()
    and p.title ilike v_source.title || ' — Draft%'
    and regexp_match(p.title, '— Draft (\d+)$') is not null;

  v_draft_num := 2;
  while v_used_numbers is not null and v_draft_num = any(v_used_numbers) loop
    v_draft_num := v_draft_num + 1;
  end loop;

  v_new_title := v_source.title || ' — Draft ' || v_draft_num;

  insert into public.projects (user_id, title, description, cover_color, word_count)
  values (auth.uid(), v_new_title, v_source.description, v_source.cover_color, v_source_total)
  returning * into v_new_project;

  for v_source_chapter in
    select * from public.chapters where project_id = p_project_id order by position
  loop
    insert into public.chapters (project_id, title, position)
    values (v_new_project.id, v_source_chapter.title, v_source_chapter.position)
    returning id into v_new_chapter_id;

    for v_source_page in
      select * from public.pages where chapter_id = v_source_chapter.id order by position
    loop
      insert into public.pages (chapter_id, title, content, word_count, position, is_canonical)
      values (
        v_new_chapter_id,
        v_source_page.title,
        v_source_page.content,
        v_source_page.word_count,
        v_source_page.position,
        v_source_page.is_canonical
      );
    end loop;
  end loop;

  return jsonb_build_object('status', 'ok', 'project', to_jsonb(v_new_project));
end;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_single_canonical_page()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.pages
  set is_canonical = false
  where chapter_id = new.chapter_id
    and id <> new.id
    and is_canonical = true;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.free_word_limit_for_caller()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_tier text;
  v_cohort text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select subscription_tier into v_tier from public.profiles where id = auth.uid();
  if coalesce(v_tier, 'free') <> 'free' then
    return null;
  end if;

  select coalesce(pricing_cohort, 'starter_2k') into v_cohort
    from public.user_pricing_entitlements where user_id = auth.uid();

  return case coalesce(v_cohort, 'starter_2k')
    when 'legacy_15k' then 15000
    else 2000
  end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.profiles (
    id,
    display_name,
    avatar_url,
    xp,
    level,
    has_written_first_words,
    subscription_tier
  ) values (
    new.id,
    new.raw_user_meta_data ->> 'display_name',
    new.raw_user_meta_data ->> 'avatar_url',
    0,
    1,
    false,
    'free'
  );

  insert into public.user_pricing_entitlements (
    user_id,
    pricing_cohort,
    founder_offer_status
  ) values (
    new.id,
    'starter_2k',
    'not_offered'
  );

  return new;
end;
$function$;

-- Unused by the app. SECURITY DEFINER without a pinned search_path, trusts
-- p_user_id, and is executable by PUBLIC/anon. Recorded as-is; hardening is a
-- separate, explicitly approved change.
CREATE OR REPLACE FUNCTION public.increment_game_ticket(p_user_id uuid, p_week_start date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  INSERT INTO public.game_tickets (user_id, week_start, tickets_used)
  VALUES (p_user_id, p_week_start, 1)
  ON CONFLICT (user_id, week_start)
  DO UPDATE SET tickets_used = game_tickets.tickets_used + 1;
END;
$function$;

CREATE OR REPLACE FUNCTION public.increment_page_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.version = OLD.version + 1;
  NEW.updated_at = now(); -- Genrates a high-precision timestamptz locally on the Postgres server
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.insert_page_checked(p_chapter_id uuid, p_title text, p_content jsonb, p_word_count integer, p_position integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_limit int;
  v_new_total int;
  v_new public.pages%rowtype;
begin
  perform public.lock_account_word_budget();

  if p_word_count > 0 then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_new_total := public.account_word_total(null, p_word_count);
      if v_new_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  insert into public.pages (chapter_id, title, content, word_count, position, is_canonical)
  values (p_chapter_id, p_title, p_content, p_word_count, p_position, false)
  returning * into v_new;

  return jsonb_build_object('status', 'ok', 'id', v_new.id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.lock_account_word_budget()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  perform pg_advisory_xact_lock(('x' || substr(md5(auth.uid()::text), 1, 16))::bit(64)::bigint);
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_billing_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.role() = 'authenticated' then
    if new.subscription_tier is distinct from old.subscription_tier then
      new.subscription_tier := old.subscription_tier;
    end if;
    if new.subscription_status is distinct from old.subscription_status then
      new.subscription_status := old.subscription_status;
    end if;
    if new.subscription_price_id is distinct from old.subscription_price_id then
      new.subscription_price_id := old.subscription_price_id;
    end if;
    if new.subscription_period_end is distinct from old.subscription_period_end then
      new.subscription_period_end := old.subscription_period_end;
    end if;
    if new.stripe_customer_id is distinct from old.stripe_customer_id then
      new.stripe_customer_id := old.stripe_customer_id;
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_is_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.role() = 'authenticated' and new.is_admin is distinct from old.is_admin then
    new.is_admin := old.is_admin;
  end if;
  return new;
end;
$function$;

-- Save-path RPC (migration 011). Signature, argument names, return shape and
-- status values are a contract with stale clients — never overload or extend.
CREATE OR REPLACE FUNCTION public.save_page_checked(p_page_id uuid, p_content jsonb, p_word_count integer, p_expected_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_old_word_count int;
  v_limit int;
  v_new_total int;
  v_updated public.pages%rowtype;
begin
  perform public.lock_account_word_budget();

  select p.word_count
    into v_old_word_count
    from public.pages p
    where p.id = p_page_id;

  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Page not found');
  end if;

  -- Only enforce when words are being added — never block edits/deletions.
  -- A page that's already over the allowance (legacy data, a prior
  -- inconsistency) is never trapped: shrinking or net-neutral edits always
  -- pass, only further growth is blocked.
  if p_word_count > v_old_word_count then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_new_total := public.account_word_total(p_page_id, p_word_count);
      if v_new_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  if p_expected_version is not null then
    update public.pages
       set content = p_content, word_count = p_word_count
     where id = p_page_id and version = p_expected_version
     returning * into v_updated;

    if not found then
      return jsonb_build_object('status', 'version_mismatch');
    end if;
  else
    update public.pages
       set content = p_content, word_count = p_word_count
     where id = p_page_id
     returning * into v_updated;

    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Page not found');
    end if;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'updated_at', v_updated.updated_at,
    'version', v_updated.version
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.touch_pricing_entitlement_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

