revoke execute on function public.account_word_total(p_candidate_page_id uuid, p_candidate_word_count integer) from public;
revoke execute on function public.duplicate_project_checked(p_project_id uuid) from public;
revoke execute on function public.free_word_limit_for_caller() from public;
revoke execute on function public.insert_page_checked(p_chapter_id uuid, p_title text, p_content jsonb, p_word_count integer, p_position integer) from public;
revoke execute on function public.lock_account_word_budget() from public;
revoke execute on function public.save_page_checked(p_page_id uuid, p_content jsonb, p_word_count integer, p_expected_version integer) from public;

