-- Tables with RLS enabled and no policy below are service-role only.

-- The unnamed-style "Users can manage …" FOR ALL policies on projects, chapters
-- and pages predate the per-command "…: <cmd> own" policies. Both sets exist in
-- production and are permissive (OR-ed). Any change to ownership rules must
-- account for both.

create policy "chapters: delete own" on public.chapters
  as permissive for delete to public
  using ((EXISTS ( SELECT 1
   FROM projects
  WHERE ((projects.id = chapters.project_id) AND (projects.user_id = auth.uid())))));

create policy "chapters: insert own" on public.chapters
  as permissive for insert to public
  with check ((EXISTS ( SELECT 1
   FROM projects
  WHERE ((projects.id = chapters.project_id) AND (projects.user_id = auth.uid())))));

create policy "chapters: select own" on public.chapters
  as permissive for select to public
  using ((EXISTS ( SELECT 1
   FROM projects
  WHERE ((projects.id = chapters.project_id) AND (projects.user_id = auth.uid())))));

create policy "chapters: update own" on public.chapters
  as permissive for update to public
  using ((EXISTS ( SELECT 1
   FROM projects
  WHERE ((projects.id = chapters.project_id) AND (projects.user_id = auth.uid())))));

create policy "Users can manage chapters of their projects" on public.chapters
  as permissive for all to public
  using ((project_id IN ( SELECT projects.id
   FROM projects
  WHERE (projects.user_id = auth.uid()))));

create policy "future_letters: delete own" on public.future_letters
  as permissive for delete to public
  using ((auth.uid() = user_id));

create policy "future_letters: insert own" on public.future_letters
  as permissive for insert to public
  with check ((auth.uid() = user_id));

create policy "future_letters: select own" on public.future_letters
  as permissive for select to public
  using ((auth.uid() = user_id));

create policy "future_letters: update own" on public.future_letters
  as permissive for update to public
  using ((auth.uid() = user_id));

create policy "game_sessions: delete own" on public.game_sessions
  as permissive for delete to public
  using ((auth.uid() = user_id));

create policy "game_sessions: insert own" on public.game_sessions
  as permissive for insert to public
  with check ((auth.uid() = user_id));

create policy "game_sessions: select own" on public.game_sessions
  as permissive for select to public
  using ((auth.uid() = user_id));

create policy "game_sessions: update own" on public.game_sessions
  as permissive for update to public
  using ((auth.uid() = user_id));

create policy "Users manage own tickets" on public.game_tickets
  as permissive for all to public
  using ((auth.uid() = user_id));

create policy "pages: delete own" on public.pages
  as permissive for delete to public
  using ((EXISTS ( SELECT 1
   FROM (chapters
     JOIN projects ON ((projects.id = chapters.project_id)))
  WHERE ((chapters.id = pages.chapter_id) AND (projects.user_id = auth.uid())))));

create policy "pages: insert own" on public.pages
  as permissive for insert to public
  with check ((EXISTS ( SELECT 1
   FROM (chapters
     JOIN projects ON ((projects.id = chapters.project_id)))
  WHERE ((chapters.id = pages.chapter_id) AND (projects.user_id = auth.uid())))));

create policy "pages: select own" on public.pages
  as permissive for select to public
  using ((EXISTS ( SELECT 1
   FROM (chapters
     JOIN projects ON ((projects.id = chapters.project_id)))
  WHERE ((chapters.id = pages.chapter_id) AND (projects.user_id = auth.uid())))));

create policy "pages: update own" on public.pages
  as permissive for update to public
  using ((EXISTS ( SELECT 1
   FROM (chapters
     JOIN projects ON ((projects.id = chapters.project_id)))
  WHERE ((chapters.id = pages.chapter_id) AND (projects.user_id = auth.uid())))));

create policy "Users can manage pages in their chapters" on public.pages
  as permissive for all to public
  using ((chapter_id IN ( SELECT c.id
   FROM (chapters c
     JOIN projects p ON ((c.project_id = p.id)))
  WHERE (p.user_id = auth.uid()))));

create policy "profiles: select own" on public.profiles
  as permissive for select to public
  using ((auth.uid() = id));

create policy "profiles: update own" on public.profiles
  as permissive for update to public
